<?php $badge = function ($s) { include APP_ROOT . '/views/partials/status.php'; }; $out = jdec($t['output'], []); ?>
<div class="topbar"><div><a class="small" href="/admin/tasks">← Tasks</a><h1><?= e($t['title']) ?></h1><span class="muted small">#<?= (int)$t['id'] ?> · <?= e($t['public_id']) ?> · <?= e($t['kind']) ?> · <a href="/admin/agents/<?= e($t['agent_slug']) ?>"><?= e($t['agent_slug']) ?></a> · by <?= e($t['created_by']) ?></span></div>
  <div class="row"><?php $badge($t['status']); ?>
  <?php if (in_array($t['status'], ['failed', 'cancelled', 'needs_info'], true)): ?><form method="post" action="/admin/tasks/<?= (int)$t['id'] ?>/retry"><?= App\Csrf::field() ?><button class="btn btn-primary btn-sm">Retry</button></form><?php endif; ?>
  <?php if (in_array($t['status'], ['queued', 'blocked'], true)): ?><form method="post" action="/admin/tasks/<?= (int)$t['id'] ?>/run"><?= App\Csrf::field() ?><button class="btn btn-ghost btn-sm">Run now</button></form><?php endif; ?>
  <?php if (in_array($t['status'], ['queued', 'needs_approval', 'needs_info', 'blocked', 'failed'], true)): ?><form method="post" action="/admin/tasks/<?= (int)$t['id'] ?>/cancel" data-confirm="Cancel this task?"><?= App\Csrf::field() ?><button class="btn btn-danger btn-sm">Cancel</button></form><?php endif; ?></div></div>
<div class="grid g2" style="align-items:start"><div class="panel"><h2>Input</h2><pre><?= e(json_encode(jdec($t['input']), JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)) ?></pre>
  <h2>Result</h2><?php if (!empty($out['summary'])): ?><p><?= nl2br(e($out['summary'])) ?></p><?php else: ?><p class="muted small">No output yet.</p><?php endif; ?>
  <?php if ($t['error']): ?><div class="alert alert-error small"><?= e($t['error']) ?></div><?php endif; ?>
  <p class="small muted">Attempts <?= (int)$t['attempts'] ?>/<?= (int)$t['max_attempts'] ?> · run after <?= e($t['run_after']) ?> · tokens <?= (int)$t['tokens_in'] ?>/<?= (int)$t['tokens_out'] ?> · $<?= number_format($t['cost_micros'] / 1e6, 4) ?><?= $t['project_id'] ? ' · project #' . (int)$t['project_id'] : '' ?></p></div>
<div class="panel"><h2>Runs</h2><?php if (!$runs): ?><p class="small muted">Not run yet.</p><?php endif; ?><?php foreach ($runs as $r): ?><div class="small" style="padding:6px 0;border-bottom:1px solid var(--line-2)"><?php $badge($r['status']); ?> <?= e($r['created_at']) ?> · <?= e($r['model']) ?> · <?= (int)$r['iterations'] ?> steps · <?= (int)$r['duration_ms'] ?>ms · tools: <?= e(implode(', ', jdec($r['tools_used']))) ?></div><?php endforeach; ?>
  <?php if ($children): ?><h2 style="margin-top:14px">Subtasks</h2><?php foreach ($children as $c): ?><div class="small"><a href="/admin/tasks/<?= (int)$c['id'] ?>"><?= e($c['title']) ?></a> · <?= e($c['agent_slug']) ?> · <?= e($c['status']) ?></div><?php endforeach; endif; ?></div></div>
